<script setup>
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {api} from '../lib/api'
import {characterAtStage} from '../data/evolutions'
import {cardLevels} from '../data/card-levels'
import {hiddenLevels} from '../data/hidden-levels'
import {formatGameTime} from '../lib/gameTime'
const props=defineProps({game:{type:String,default:'cards'},level:{type:Number,default:1}}),emit=defineEmits(['close']),dialog=ref(null),selectedGame=ref(props.game==='hidden'?'hidden':'cards'),level=ref(Math.max(1,Math.min(props.level,props.game==='hidden'?10:8))),result=ref(null),loading=ref(false),error=ref('')
const levels=computed(()=>selectedGame.value==='cards'?cardLevels:hiddenLevels),podium=computed(()=>[2,1,3].map(rank=>({rank,entry:result.value?.entries.find(e=>e.rank===rank),medal:({1:'🥇',2:'🥈',3:'🥉'})[rank],name:({1:'금메달',2:'은메달',3:'동메달'})[rank]})))
let alive=true,request=0
async function load(){const current=++request;loading.value=true;error.value='';result.value=null;try{const data=await api('/game-rankings?game='+selectedGame.value+'&level='+level.value);if(alive&&current===request)result.value=data}catch(e){if(alive&&current===request)error.value=e.message}finally{if(alive&&current===request)loading.value=false}}
function changeGame(value){selectedGame.value=value;level.value=1}
function close(){dialog.value.close();emit('close')}
watch([selectedGame,level],load)
onMounted(()=>{dialog.value.showModal();load()});onUnmounted(()=>{alive=false;request++})
const medalLabel=entry=>entry?.medal?({gold:'🥇 금메달',silver:'🥈 은메달',bronze:'🥉 동메달'})[entry.medal]:'메달 도전 중'
</script>
<template><dialog ref="dialog" class="game-hall" aria-labelledby="game-hall-title" @cancel.prevent="close"><div class="hall-header"><div><small>SPOKEMON / HALL OF FAME</small><h2 id="game-hall-title">🏆 명예의 전당</h2></div><button class="light" aria-label="명예의 전당 닫기" @click="close">✕</button></div><div class="hall-filters"><label>게임<select aria-label="게임" :value="selectedGame" @change="changeGame($event.target.value)"><option value="cards">카드 뒤집기</option><option value="hidden">숨은그림 찾기</option></select></label><label>단계<select aria-label="단계" v-model.number="level"><option v-for="item in levels" :key="item.id" :value="item.id">LEVEL {{item.id}} · {{item.name}}</option></select></label><button class="light" :disabled="loading" @click="load">새로고침</button></div><p class="hall-rule">단계별 개인 최고 기록 · 완료 시간이 빠른 순서예요. 동률은 {{selectedGame==='cards'?'시도 횟수':'실수·힌트 횟수'}}가 적은 순, 먼저 달성한 순서로 정해요.</p><p v-if="loading" class="hall-state" role="status">기록을 불러오는 중…</p><p v-else-if="error" class="notice" role="alert">{{error}}</p><template v-else-if="result"><div class="hall-podium" aria-label="금 은 동 메달 순위"><article v-for="slot in podium" :key="slot.rank" :class="['hall-podium-place','hall-place-'+slot.rank]" :aria-label="slot.rank+'위 '+(slot.entry?slot.entry.nickname+' '+formatGameTime(slot.entry.durationMs):'기록 없음')"><span class="hall-medal" :aria-label="slot.name">{{slot.medal}}</span><img v-if="slot.entry" :src="characterAtStage(slot.entry.character,slot.entry.stage).image" :alt="characterAtStage(slot.entry.character,slot.entry.stage).name"/><span v-else class="hall-empty-avatar" aria-hidden="true">?</span><b>{{slot.entry?.nickname??'도전자를 기다려요'}}</b><small v-if="slot.entry">@{{slot.entry.login}}</small><strong>{{slot.entry?formatGameTime(slot.entry.durationMs):'기록 없음'}}</strong><span class="hall-podium-base">{{slot.rank}}위 · {{slot.name}}</span></article></div><section class="hall-my-record" aria-label="나의 최고 기록"><template v-if="result.me"><b>내 최고 기록 · {{result.me.rank}}위</b><strong>{{formatGameTime(result.me.durationMs)}}</strong><span>{{medalLabel(result.me)}}</span></template><template v-else><b>내 최고 기록</b><span>이 단계를 완료하면 기록이 등록돼요!</span></template></section><div class="hall-list-heading"><h3>최고 기록 TOP 20</h3><span>참가자 {{result.totalPlayers}}명</span></div><p v-if="!result.entries.length" class="hall-state">아직 완료 기록이 없어요. 첫 번째 주인공이 되어 보세요!</p><ol v-else class="hall-ranking-list"><li v-for="entry in result.entries" :key="entry.login" :value="entry.rank" :class="['hall-row',{'hall-is-me':entry.isMe}]" :aria-label="entry.rank+'위 '+entry.nickname+' '+formatGameTime(entry.durationMs)"><span class="hall-rank">{{entry.rank<=3?({1:'🥇',2:'🥈',3:'🥉'})[entry.rank]:entry.rank}}</span><div class="hall-player"><img :src="characterAtStage(entry.character,entry.stage).image" alt=""/><div><b>{{entry.nickname}} <small v-if="entry.isMe">나</small></b><span>@{{entry.login}}</span></div></div><strong class="hall-time">{{formatGameTime(entry.durationMs)}}</strong><small class="hall-detail">{{selectedGame==='cards'?'시도 '+entry.attempts+'회':'실수 '+entry.attempts+' · 힌트 '+entry.hints}}</small></li></ol><p class="hall-note">서버가 시작부터 완료까지 잰 시간으로 저장해요. 메달은 현재 순위 기준이며, 순위가 바뀌면 함께 변경됩니다.</p></template></dialog></template>
<style scoped>
