);font-size:12px;font-weight:bold}.hall-place-1{border-color:#bd8b25}.hall-place-1 .hall-podium-base{background:linear-gradient(#ffe487,#edbd46);color:#6a460c;padding-top:21px}.hall-place-1 .hall-medal{font-size:43px}.hall-place-1>img{height:86px;width:76px}.hall-place-2{border-color:#8796b1}.hall-place-2 .hall-podium-base{background:linear-gradient(#e6edf6,#aebbd2);color:#32435e}.hall-place-3{border-color:#b47f56}.hall-place-3 .hall-podium-base{background:linear-gradient(#f2c9a1,#cc9467);color:#58351b;padding-top:6px}.hall-my-record{border:2px solid var(--rpg-edge);border-radius:9px;background:var(--rpg-soft);padding:13px 16px;display:flex;gap:16px;align-items:center;flex-wrap:wrap;font-size:12px}.hall-my-record strong{font-size:22px}.hall-my-record>span{margin-left:auto}.hall-list-heading{display:flex;align-items:center;justify-content:space-between;gap:10px;margin:20px 0 9px}.hall-list-heading h3{font-size:17px;margin:0}.hall-list-heading>span{font-size:10px}.hall-ranking-list{list-style:none;margin:0;padding:0}.hall-row{display:grid;grid-template-columns:42px minmax(0,1fr) 112px 110px;gap:12px;align-items:center;min-height:62px;border-top:1px solid var(--rpg-bright);padding:8px}.hall-rank{font-size:22px;text-align:center}.hall-player{display:flex;align-items:center;gap:9px;min-width:0}.hall-player>img{width:34px;height:38px;object-fit:contain;flex:none}.hall-player>div{min-width:0}.hall-player b{font-size:12px;display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.hall-player b>small{font-size:9px;background:var(--rpg-mid);padding:2px 4px;border-radius:3px}.hall-player div>span{font-size:9px;display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.hall-time{text-align:right;font-size:15px}.hall-detail{font-size:10px;text-align:right}.hall-is-me{background:var(--rpg-soft);border-radius:5px}.hall-state{padding:22px 8px;text-align:center;font-size:13px}@media(max-width:600px){.game-hall{padding:15px;max-height:92dvh}.hall-header h2{font-size:22px}.hall-filters{grid-template-columns:1fr 1fr;gap:9px}.hall-filters>button{grid-column:1/-1;justify-self:end;padding:7px 12px}.hall-filters select{font-size:10px}.hall-podium{gap:6px}.hall-podium-place{padding:8px 4px 0}.hall-podium-place>img{width:46px;height:57px}.hall-place-1>img{width:56px;height:65px}.hall-podium-place>b{font-size:11px}.hall-podium-place>small{font-size:8px}.hall-podium-place>strong{font-size:13px}.hall-podium-base{font-size:10px}.hall-medal{font-size:27px}.hall-place-1 .hall-medal{font-size:35px}.hall-empty-avatar{height:57px}.hall-my-record{padding:10px;gap:8px;font-size:11px}.hall-my-record strong{font-size:17px}.hall-my-record>span{margin-left:0}.hall-row{grid-template-columns:26px minmax(0,1fr) 85px;gap:6px;padding:7px 2px}.hall-player{gap:5px}.hall-player>img{width:27px}.hall-player b{font-size:11px}.hall-time{font-size:12px}.hall-detail{display:none}.hall-rank{font-size:20px}.hall-list-heading h3{font-size:15px}}
